fn encode(message: Vec<char>) -> Vec<char> {
    // Helper function to check if a char is a vowel
    fn is_vowel(c: char) -> bool {
        matches!(c, 'a' | 'e' | 'i' | 'o' | 'u' | 'A' | 'E' | 'I' | 'O' | 'U')
    }

    // Helper function to map vowel to its replacement char
    // Given a vowel c, return the mapped char according to problem statement,
    // preserving case (uppercase maps to uppercase, lowercase to lowercase)
    fn map_vowel(c: char) -> char {
        match c {
            'a' => 'c',
            'e' => 'g',
            'i' => 'k',
            'o' => 'q',
            'u' => 'w',
            'A' => 'C',
            'E' => 'G',
            'I' => 'K',
            'O' => 'Q',
            'U' => 'W',
            _ => c, // should never reach here
        }
    }

    // Helper function to swap case of a character guaranteed to be a letter
    fn swap_case(c: char) -> char {
        if c.is_ascii_uppercase() {
            c.to_ascii_lowercase()
        } else {
            c.to_ascii_uppercase()
        }
    }

    // Process each character according to the rules
    message
        .into_iter()
        .map(|c| {
            if c == ' ' {
                // space remains space
                ' '
            } else if is_vowel(c) {
                // map vowel then swap case
                let mapped = map_vowel(c);
                swap_case(mapped)
            } else {
                // consonant: just swap case
                swap_case(c)
            }
        })
        .collect()
}